        "data-app-action-sidebar-thread-id",
        "data-app-action-sidebar-thread-kind",
        "data-app-action-sidebar-thread-host-id",
        "inert",
        "aria-hidden",
        "hidden",
        "data-aria-hidden",
        "data-inert-ed",
        "data-composer-placement",
